        "Форми: er bleibt, blieb, ist geblieben. В миналото време с причастие като спомагателен се използва sein, а не haben: Ich bin zu Hause geblieben.",
        "След bleiben може да стои място или прилагателно; с инфинитив образува изрази: stehen bleiben (спирам), sitzen bleiben (оставам седнал)."
