        "Отделен брат или сестра се означава с der Bruder или die Schwester. Членът е die Geschwister, а глаголът е в множествено число: Meine Geschwister wohnen in Hamburg. В дателен падеж: mit meinen Geschwistern.",
        "Думата не показва пола: Ich habe zwei Geschwister може да означава братя, сестри или и двете."
