        "Накратко: думата wissen означава „знам” факт, информация или отговор, които човек е научил или разбрал. Ich weiß die Antwort — знам отговора.",
        "Формите са неправилни: ich weiß, du weißt, er/sie/es weiß, wir wissen; минало време wusste, Perfekt hat gewusst. Често се използва с подчинено изречение с dass или с въпросителна дума: Ich weiß, dass… / Weißt du, wo…?",
        "Разлика от kennen: wissen — факт, kennen — познавам човек или място."
