        "Форми: legt, legte, hat gelegt (спада към правилните глаголи). Възвратно: sich legen — лягам: Ich lege mich ins Bett. Понякога и „снасям (яйца)”: Die Henne legt Eier.",
        "Разлика от liegen: legen изразява действие (накъде?), liegen — състояние (къде?): Ich lege das Buch auf den Tisch, но Das Buch liegt auf dem Tisch."
