      "id": "a1-müssen",
      "layout": "standardStudy",
      "translation": "трябва • длъжен съм",
      "explanation": [
        "Накратко: думата müssen е от модалните глаголи — „трябва, длъжен съм”: Ich muss gehen — трябва да тръгвам. Изразява необходимост или задължение.",
        "Форми: ich muss, du musst, er/sie/es muss, wir müssen, ihr müsst, sie müssen; musste, hat gemusst. Глаголът след него стои в инфинитив в края на изречението: Ich muss heute arbeiten.",
        "Важно: nicht müssen означава „не е необходимо”, а не „не бива”: Du musst nicht kommen — не е необходимо да идваш. „Не бива” е nicht dürfen."
      ],
      "examples": [
        {
          "de": "Ich muss jetzt gehen.",
          "lv": "Сега трябва да тръгвам."
        },
        {
          "de": "Du musst warten.",
          "lv": "Трябва да чакаш."
        },
        {
          "de": "Wir müssen lernen.",
          "lv": "Трябва да учим."
        },
        {
          "de": "Ich muss heute arbeiten.",
          "lv": "Днес трябва да работя."
        },
        {
          "de": "Du musst nicht kommen.",
          "lv": "Няма нужда да идваш."
        }
      ],
      "comparison": [
        {
          "word": "sollen",
          "meaning": "трябва (по указание)",
          "example": "Du sollst mehr schlafen. – Трябва да спиш повече."
        },
        {
          "word": "dürfen",
          "meaning": "имам право, позволено ми е",
          "example": "Hier darf man nicht rauchen. – Тук не бива да се пуши."
        },
        {
          "word": "brauchen",
          "meaning": "имам нужда (от нещо)",
          "example": "Ich brauche Hilfe. – Имам нужда от помощ."
        }
      ],
      "tip": [
        "Muss е по-силно от sollen: muss = задължително, soll = по нечие указание.",
        "Ако искаш да кажеш „не е необходимо”, казвай nicht müssen или nicht brauchen zu."
      ],
      "important": [
        "Nicht müssen ≠ nicht dürfen: Du musst nicht gehen (не е задължително) ≠ Du darfst nicht gehen (забранено е).",
        "Müssen не се използва със zu: Ich muss gehen, а не „Ich muss zu gehen”."
      ],
