      "explanation": [
        "Накратко: die Seite е съществително от женски род, множествено число die Seiten. Има няколко значения: страница в книга или тетрадка (Seite 5), страна (linke Seite — лявата страна), интернет страница и аспект (eine gute Seite — добра страна).",
        "Страницата се посочва с auf Seite + число, без член: auf Seite 20. Когато се говори за местоположение, се използва auf der Seite (Dat): auf der rechten Seite.",
        "Лист хартия като отделен предмет се нарича das Blatt, а не die Seite."
      ],
