        "На български може да отговаря на „ако“ (условие: wenn du willst) или на „когато“ (повторение или момент в бъдещето: immer wenn, wenn ich Zeit habe). Ако подчиненото изречение е на първо място, в главното изречение глаголът следва веднага след запетаята.",
        "Еднократно събитие в миналото не се изразява с wenn, а с als: Als ich klein war ..."
