        "Въпрос за часа: Wie viel Uhr ist es? или Wie spät ist es? Продължителността в часове се изразява с die Stunde: zwei Stunden.",
        "Uhr означава момент във времето (um acht Uhr), а Stunde — продължителност (acht Stunden); не бива да се бъркат."
